    'backup.last': ['Letztes Backup: {d} ({r})', 'Last backup: {d} ({r})', 'Dernière sauvegarde : {d} ({r})', 'Última copia: {d} ({r})', 'Ultimo backup: {d} ({r})', 'Senaste säkerhetskopia: {d} ({r})', 'Seneste backup: {d} ({r})'],
    'backup.never': ['Noch nie ein Backup heruntergeladen', 'No backup downloaded yet', 'Aucune sauvegarde téléchargée', 'Aún no se ha descargado ninguna copia', 'Nessun backup ancora scaricato', 'Ingen säkerhetskopia nedladdad än', 'Ingen backup downloadet endnu'],
    'backup.recommend': ['Empfehlung: einmal pro Woche sichern', 'Recommended: back up once a week', 'Conseil : sauvegarder une fois par semaine', 'Recomendado: una copia a la semana', 'Consigliato: un backup a settimana', 'Rekommendation: en gång i veckan', 'Anbefaling: én gang om ugen'],
    'backup.confirm': ['Backup „{f}“ wiederherstellen? Fehlende Daten werden ergänzt, vorhandene bleiben unverändert.', 'Restore backup “{f}”? Missing data will be added, existing data stays unchanged.', 'Restaurer la sauvegarde « {f} » ? Les données manquantes seront ajoutées, les existantes restent inchangées.', '¿Restaurar la copia «{f}»? Se añadirán los datos que faltan; los existentes no cambian.', 'Ripristinare il backup «{f}»? I dati mancanti verranno aggiunti, quelli esistenti restano invariati.', 'Återställa ”{f}”? Saknade data läggs till, befintliga lämnas orörda.', 'Gendan backup “{f}”? Manglende data tilføjes, eksisterende forbliver uændrede.'],
